-- Run inside the nested Z0001 rollback block after the migration. All rows are synthetic.
DECLARE client uuid:=gen_random_uuid(); other_client uuid:=gen_random_uuid(); partner uuid:=gen_random_uuid(); app uuid; offer uuid; claim uuid;
 client_hash text:=encode(digest(gen_random_uuid()::text,'sha256'),'hex'); partner_hash text:=encode(digest(gen_random_uuid()::text,'sha256'),'hex');
 other_hash text:=encode(digest(gen_random_uuid()::text,'sha256'),'hex'); version text; offer_version text; claim_version text; request uuid:=gen_random_uuid(); r jsonb; replay jsonb; payload jsonb; access uuid;
BEGIN
 INSERT INTO public.client_profiles(id,display_name,contact) VALUES(client,'PCS rollback client','test-only'),(other_client,'PCS rollback other','test-only-other');
 INSERT INTO public.partners(id,public_name,status) VALUES(partner,'PCS rollback partner','ACTIVE');
 PERFORM pcs.portal_admin_action('issue-access',jsonb_build_object('role','CLIENT','profile_id',client,'hash',client_hash));
 PERFORM pcs.portal_admin_action('issue-access',jsonb_build_object('role','CLIENT','profile_id',other_client,'hash',other_hash));
 PERFORM pcs.portal_admin_action('issue-access',jsonb_build_object('role','PARTNER','profile_id',partner,'hash',partner_hash));
 payload:=jsonb_build_object('need','Synthetic test service','city','Test');
 r:=pcs.portal_action(client_hash,'request',request,payload); app:=(r->>'application_id')::uuid;
 replay:=pcs.portal_action(client_hash,'request',request,payload); IF r<>replay THEN RAISE EXCEPTION 'QA replay failed'; END IF;
 BEGIN PERFORM pcs.portal_action(client_hash,'request',request,jsonb_build_object('need','Different')); RAISE EXCEPTION 'QA changed replay accepted'; EXCEPTION WHEN unique_violation THEN NULL; END;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 BEGIN PERFORM pcs.portal_action(other_hash,'confirm',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version)); RAISE EXCEPTION 'QA cross-client access accepted'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 PERFORM pcs.portal_admin_action('assign-partner',jsonb_build_object('application_id',app,'expected_version',version,'partner_id',partner));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 r:=pcs.portal_action(partner_hash,'submit-offer',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version,'price','1000','deposit','200','terms','Synthetic terms')); offer:=(r->>'offer_id')::uuid;
 IF jsonb_array_length(pcs.portal_home(client_hash)->'offers')<>0 THEN RAISE EXCEPTION 'QA unapproved offer leaked'; END IF;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;SELECT updated_at::text INTO offer_version FROM public.pcs_partner_offers WHERE id=offer;
 PERFORM pcs.portal_admin_action('review-offer',jsonb_build_object('application_id',app,'expected_version',version,'offer_id',offer,'offer_version',offer_version,'decision','APPROVED'));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 PERFORM pcs.portal_action(client_hash,'select-offer',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version,'offer_id',offer));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 BEGIN PERFORM pcs.portal_action(client_hash,'confirm',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version)); RAISE EXCEPTION 'QA client confirmed before partner'; EXCEPTION WHEN check_violation THEN NULL; END;
 PERFORM pcs.portal_action(partner_hash,'confirm',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 PERFORM pcs.portal_action(client_hash,'confirm',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 BEGIN PERFORM pcs.portal_action(client_hash,'payment',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version,'amount','400','reference','test-transfer')); RAISE EXCEPTION 'QA payment before instructions'; EXCEPTION WHEN check_violation THEN NULL; END;
 PERFORM pcs.portal_admin_action('payment-instructions',jsonb_build_object('application_id',app,'expected_version',version,'instructions','Synthetic test bank instructions'));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 r:=pcs.portal_action(client_hash,'payment',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version,'amount','400','reference','test-transfer'));claim:=(r->>'claim_id')::uuid;
 IF (SELECT client_payment_status FROM public.applications WHERE id=app)='PAID_TO_PARTNER' THEN RAISE EXCEPTION 'QA unverified payment counted'; END IF;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;SELECT updated_at::text INTO claim_version FROM pcs.application_payment_claims WHERE id=claim;
 PERFORM pcs.portal_admin_action('review-payment',jsonb_build_object('application_id',app,'expected_version',version,'claim_id',claim,'claim_version',claim_version,'decision','VERIFIED','note','Synthetic bank verification'));
 IF (SELECT client_payment_status FROM public.applications WHERE id=app)<>'PARTIALLY_PAID' THEN RAISE EXCEPTION 'QA partial payment not credited'; END IF;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 BEGIN PERFORM pcs.portal_action(client_hash,'payment',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version,'amount','400','reference','test-transfer')); RAISE EXCEPTION 'QA duplicate transfer accepted'; EXCEPTION WHEN unique_violation THEN NULL; END;
 r:=pcs.portal_action(client_hash,'payment',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version,'amount','600','reference','test-transfer-two'));claim:=(r->>'claim_id')::uuid;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;SELECT updated_at::text INTO claim_version FROM pcs.application_payment_claims WHERE id=claim;
 PERFORM pcs.portal_admin_action('review-payment',jsonb_build_object('application_id',app,'expected_version',version,'claim_id',claim,'claim_version',claim_version,'decision','VERIFIED','note','Synthetic bank verification two'));
 IF (SELECT client_payment_status FROM public.applications WHERE id=app)<>'PAID_TO_PARTNER' THEN RAISE EXCEPTION 'QA payment not credited'; END IF;
 IF (SELECT sum(amount_thb) FROM pcs.application_payment_claims WHERE application_id=app AND status='VERIFIED')<>1000 THEN RAISE EXCEPTION 'QA incorrect balance'; END IF;
 IF jsonb_array_length(pcs.portal_home(other_hash)->'applications')<>0 THEN RAISE EXCEPTION 'QA other client sees application'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(pcs.portal_home(client_hash)->'applications') x WHERE x ? 'internal_notes' OR x ? 'client_contact') THEN RAISE EXCEPTION 'QA private fields leaked'; END IF;
 SELECT id INTO access FROM pcs.portal_access WHERE token_hash=client_hash;
 PERFORM pcs.portal_admin_action('revoke-access',jsonb_build_object('access_id',access));
 BEGIN PERFORM pcs.portal_home(client_hash);RAISE EXCEPTION 'QA revoked access accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END;
